import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type CalendarSceneProps = Record<string, any>;

const CalendarScene: React.FC<CalendarSceneProps> = ({
  backgroundColor = "#07090f",
  transparentBackground = false,
  durationInSeconds = 8,
  monthName = "MARCH",
  eventName = "AI Agent & Copilot Summit",
  highlightColor = "#3b82f6",
  textColor = "#ffffff",
  gridOpacity = 0.4,
  startHighlightDate = 17,
  endHighlightDate = 19,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Space Grotesk"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // 1. Entrance Animations
  const sceneEntrance = spring({
    frame: frame - 5,
    fps,
    config: { damping: 14, stiffness: 90 },
  });

  const headerY = interpolate(sceneEntrance, [0, 1], [80, 0]);
  const headerOpacity = interpolate(sceneEntrance, [0, 1], [0, 1]);

  // 2. Layout & Calendar Calculations
  // Ensuring responsive constraints primarily for 9:16 mobile optimization
  const containerWidth = width * 0.85;
  const cellWidth = containerWidth / 7;
  const cellHeight = cellWidth; // Square grid
  
  // Hardcoded offset logic to ensure 17,18,19 are consecutive on a stable row
  // We offset the start of the month by 0 (Sunday) to align them on the same row.
  const startIndex = startHighlightDate - 1;
  const endIndex = endHighlightDate - 1;
  
  const startRow = Math.floor(startIndex / 7);
  const startCol = startIndex % 7;
  const endCol = endIndex % 7;
  const spanCount = endCol - startCol + 1;

  // 3. Highlight Animation Sequence
  const highlightStartFrame = 50;
  const highlightProgress = spring({
    frame: frame - highlightStartFrame,
    fps,
    config: { damping: 15, mass: 0.8 },
  });

  const targetHighlightWidth = spanCount * cellWidth;
  // Compute width ensuring we don't drop below 0 during extreme under-damping, 
  // and subtract a small padding factor so the pill fits inside the grid cleanly.
  const paddingX = cellWidth * 0.15;
  const currentHighlightWidth = Math.max(
    0, 
    (highlightProgress * targetHighlightWidth) - (paddingX * 2)
  );

  // 4. Highlight Pulse Loop (Focus Element)
  const pulseStartFrame = highlightStartFrame + 25;
  const pulseOffset = frame > pulseStartFrame ? frame - pulseStartFrame : 0;
  const pulseScale = 1 + Math.sin(pulseOffset / 8) * 0.03;
  const pulseGlowOpacity = 0.4 + Math.sin(pulseOffset / 8) * 0.3;

  // 5. Background Motion
  const bgPanX = interpolate(frame, [0, 600], [0, 100]);
  const bgPanY = interpolate(frame, [0, 600], [0, 100]);

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: "Space Grotesk, sans-serif",
        transition: "none",
        overflow: "hidden"
      }}
    >
      {/* Background Tech Grid & Ambience */}
      <AbsoluteFill style={{ opacity: gridOpacity, transition: "none" }}>
        <div
          style={{
            position: "absolute",
            width: "200%",
            height: "200%",
            backgroundSize: "60px 60px",
            backgroundImage: `
              linear-gradient(to right, rgba(255,255,255,0.06) 1px, transparent 1px),
              linear-gradient(to bottom, rgba(255,255,255,0.06) 1px, transparent 1px)
            `,
            transform: `translate(-${bgPanX}px, -${bgPanY}px)`,
            transition: "none",
          }}
        />
        {/* Radial vignette mask to fade edges */}
        <AbsoluteFill
          style={{
            background: `radial-gradient(circle at center, transparent 30%, ${bgColor} 90%)`,
            transition: "none"
          }}
        />
      </AbsoluteFill>

      {/* Main Content Container */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          transition: "none"
        }}
      >
        <div
          style={{
            width: containerWidth,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            transition: "none"
          }}
        >
          {/* Header Section */}
          <div
            style={{
              opacity: headerOpacity,
              transform: `translateY(${headerY}px)`,
              textAlign: "center",
              display: "flex",
              flexDirection: "column",
              gap: 8,
              transition: "none"
            }}
          >
            <div
              style={{
                color: highlightColor,
                fontSize: 34,
                fontWeight: 600,
                letterSpacing: 6,
                textTransform: "uppercase",
                textShadow: `0 0 20px ${highlightColor}80`,
                transition: "none"
              }}
            >
              {eventName}
            </div>
            <div
              style={{
                color: textColor,
                fontSize: 140,
                fontWeight: 800,
                letterSpacing: -2,
                lineHeight: 1.1,
                transition: "none"
              }}
            >
              {monthName}
            </div>
          </div>

          {/* Calendar Grid Wrapper */}
          <div
            style={{
              position: "relative",
              width: containerWidth,
              height: 6 * cellHeight, // Room for header + 5 rows of days
              marginTop: 60,
              transition: "none"
            }}
          >
            {/* Weekdays Header */}
            <div style={{ display: "flex", width: "100%", height: cellHeight, transition: "none" }}>
              {["S", "M", "T", "W", "T", "F", "S"].map((day, idx) => (
                <div
                  key={`header-${idx}`}
                  style={{
                    width: cellWidth,
                    display: "flex",
                    justifyContent: "center",
                    alignItems: "center",
                    color: textColor,
                    opacity: 0.3,
                    fontWeight: 700,
                    fontSize: 28,
                    transition: "none"
                  }}
                >
                  {day}
                </div>
              ))}
            </div>

            {/* Days Grid Container */}
            <div
              style={{
                position: "absolute",
                top: cellHeight,
                left: 0,
                width: "100%",
                height: 5 * cellHeight,
                transition: "none"
              }}
            >
              {/* Connected Highlight Pill */}
              <div
                style={{
                  position: "absolute",
                  top: startRow * cellHeight + (cellHeight * 0.15),
                  left: startCol * cellWidth + paddingX,
                  height: cellHeight * 0.7,
                  width: currentHighlightWidth,
                  backgroundColor: highlightColor,
                  borderRadius: cellHeight * 0.35,
                  opacity: interpolate(highlightProgress, [0, 0.4], [0, 1], {
                    extrapolateRight: "clamp",
                  }),
                  transform: `scale(${pulseScale})`,
                  transformOrigin: "center left",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "center",
                  zIndex: 2,
                  transition: "none"
                }}
              >
                {/* Glow Layer (Focus Element) */}
                <div
                  style={{
                    position: "absolute",
                    inset: 0,
                    backgroundColor: highlightColor,
                    borderRadius: "inherit",
                    filter: "blur(20px)",
                    opacity: pulseGlowOpacity,
                    transition: "none"
                  }}
                />
              </div>

              {/* Calendar Numbers */}
              {Array.from({ length: 31 }).map((_, i) => {
                const day = i + 1;
                const r = Math.floor(i / 7);
                const c = i % 7;
                const isHighlighted = day >= startHighlightDate && day <= endHighlightDate;

                // Staggered pop-in animation
                const cellDelay = 20 + (r * 2 + c * 1.5);
                const cellPop = spring({
                  frame: frame - cellDelay,
                  fps,
                  config: { damping: 12 },
                });

                return (
                  <div
                    key={`day-${day}`}
                    style={{
                      position: "absolute",
                      top: r * cellHeight,
                      left: c * cellWidth,
                      width: cellWidth,
                      height: cellHeight,
                      display: "flex",
                      justifyContent: "center",
                      alignItems: "center",
                      fontSize: 48,
                      fontWeight: isHighlighted ? 800 : 500,
                      color: isHighlighted ? "#ffffff" : textColor,
                      transform: `scale(${Math.max(0, cellPop)})`,
                      opacity: isHighlighted ? 1 : cellPop * 0.5,
                      zIndex: isHighlighted ? 10 : 1,
                      transition: "none"
                    }}
                  >
                    {day}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default CalendarScene;